window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[41]={"id":"041","numero":41,"titre":"Endométriose","objectifs":[{"id":"41-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","contenu":"<p>Trois entités distinctes mais fréquemment associées chez la femme en âge de procréer. L’<span class=\"kw-def\">endométriose</span> n’est pas <em>systématiquement</em> pathologique : c’est sa traduction symptomatique (douleur, infertilité) qui en fait une <strong>maladie</strong>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Entité</th><th>Définition</th><th>Forme « maladie »</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Dysménorrhée</strong></td>\n            <td><span class=\"kw-clinique\">Règles douloureuses</span> — douleurs pelviennes contemporaines des menstruations</td>\n            <td>\n              <strong>Primaire / essentielle</strong> : <span class=\"kw-chiffre\">6-24 mois</span> après les 1ʳᵉˢ règles, idiopathique, sensible aux <span class=\"kw-ttt\">antalgiques</span> usuels<br>\n              <strong>Secondaire / organique</strong> : tardive, s’aggrave au fil des cycles, EVA &gt; 7/10, résistante aux antalgiques (endométriose, adénomyose, sténose cervicale…)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endométriose</strong></td>\n            <td><strong>Définition histologique</strong> : présence de <span class=\"kw-clinique\">tissu de type endométrial</span> en dehors de la cavité utérine</td>\n            <td><strong>Endométriose maladie</strong> = lorsqu’elle provoque <span class=\"kw-alerte\">douleurs</span> et/ou <span class=\"kw-alerte\">infertilité</span></td>\n          </tr>\n          <tr>\n            <td><strong>Adénomyose</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Infiltration</span> <em>diffuse ou focale</em> du <span class=\"kw-clinique\">myomètre</span> par des cellules endométriales<br>\n              → formation de <strong><span class=\"kw-etio\">microkystes endométriaux intra-myométriaux</span></strong>\n            </td>\n            <td>\n              <strong>Diffuse interne</strong> : foyers dans tout le myomètre<br>\n              <strong>Focale externe</strong> : agrégats circonscrits dans des zones précises\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Catégories anatomiques des lésions d’endométriose</h4>\n\n      <table >\n        <thead>\n          <tr><th>Forme</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Péritonéale superficielle</span></strong></td>\n            <td>\n              Lésions de petite taille, limitées au péritoine<br>\n              Aspects : rouges/florides/hémorragiques ; taches brunâtres ; microkystes noirs ; lésions étoilées blanches ; défauts péritonéaux\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Endométriome</span></strong></td>\n            <td>\n              <span class=\"kw-clinique\">Lésion</span> kystique ovarienne (<em>kyste endométriosique de l’ovaire</em>)<br>\n              Origine : invagination à point de départ à la surface de l’ovaire<br>\n              Contenu : <span class=\"kw-clinique\">liquide visqueux marron chocolat</span> (cellules détruites + sang dégradé)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Endométriose pelvienne profonde</span></strong><br><em>(sous-péritonéale)</em></td>\n            <td>\n              Nodules infiltrant à <span class=\"kw-chiffre\">&gt; 5 mm</span> sous le péritoine, à <strong>composante fibromusculaire</strong> &gt; endométriale<br>\n              Compartiment antérieur : <strong>vessie, uretères</strong><br>\n              Compartiment postérieur : <strong>ligaments utéro-sacrés, vagin, paroi antérieure rectum/sigmoïde</strong><br>\n              Autres : racines sacrées, paroi abdominale, côlon droit, appendice, iléon terminal\n            </td>\n          </tr>\n          <tr>\n            <td><strong>À distance</strong></td>\n            <td>Rares localisations : endométriose <strong>pulmonaire</strong>, <strong>cérébrale</strong>, diaphragmatique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Les 3 catégories peuvent être <em>isolées ou associées</em>. L’<span class=\"kw-clinique\">évolution</span> est <span class=\"kw-chiffre\">imprévisible</span> : certaines patientes restent toute leur vie avec des lésions superficielles, d’autres voient toutes les formes s’associer et s’aggraver en <span class=\"kw-chiffre\">&lt; 10 ans</span> de règles.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 40 — Algies pelviennes</em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/adenomyosis","label":"Radiopaedia : Adenomyosis"}]},{"id":"41-2","rang":"A","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","contenu":"<p>Maladie <span class=\"kw-def\">multifactorielle</span> (facteurs génétiques + environnementaux) dont la <strong><span class=\"kw-def\">prévalence</span> apparente augmente</strong> ces dernières décennies. Sa fréquence réelle reste difficile à chiffrer (forme asymptomatique fréquente, absence de test diagnostique simple).</p>\n\n      <h4>Endométriose</h4>\n\n      <table >\n        <thead>\n          <tr><th>Indicateur</th><th>Valeurs / population</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Âge</strong></td>\n            <td>Du diagnostic possible <em>dès la puberté</em> jusqu’à la <span class=\"kw-clinique\">ménopause</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span> générale</strong></td>\n            <td><span class=\"kw-chiffre\">6-15 %</span> des femmes en âge de procréer (toutes formes confondues)</td>\n          </tr>\n          <tr>\n            <td><strong>Femmes consultant pour infertilité</strong></td>\n            <td><span class=\"kw-chiffre\">15-20 %</span> (jusqu’à <span class=\"kw-chiffre\">50 %</span> selon séries)</td>\n          </tr>\n          <tr>\n            <td><strong>Femmes avec douleurs pelviennes</strong></td>\n            <td><span class=\"kw-chiffre\">25-33 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Retard diagnostique</strong></td>\n            <td><span class=\"kw-alerte\">7-10 ans</span> selon les études</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>FR de reflux tubaire menstruel</strong></td>\n            <td>\n              <strong>Ménarche précoce</strong> ; <strong>nulliparité</strong><br>\n              <strong>Cycles courts</strong> ; hyperménorrhée ; ménorragie<br>\n              Anomalie müllérienne (malformation utérine) ; geste endo-utérin\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Génétique</span></strong></td>\n            <td><span class=\"kw-alerte\">Risque × 5</span> chez les apparentées au 1ᵉʳ degré (variants en cours d’identification)</td>\n          </tr>\n          <tr>\n            <td><strong>Néo-nataux</strong></td>\n            <td>Petit poids de naissance ; ATCD de saignement vaginal en période néo-natale</td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>\n              ATCD d’abus ou violence sexuelle<br>\n              Faible IMC<br>\n              Perturbateurs endocriniens (rôle plausible non démontré)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Adénomyose</h4>\n\n      <ul>\n        <li><span class=\"kw-def\">Incidence</span> augmente après <span class=\"kw-chiffre\">35 ans</span></li>\n        <li>Pourrait concerner près de <span class=\"kw-chiffre\">50 %</span> des femmes</li>\n        <li>Souvent associée à l’endométriose</li>\n      </ul>","frequence":0},{"id":"41-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie de l’endométriose","contenu":"<p>La <span class=\"kw-def\">physiopathologie</span> de l’endométriose reste partiellement élucidée. La théorie dominante associe un <strong><span class=\"kw-def\">reflux tubaire de sang menstruel</span></strong> à une <strong>capacité d’élimination péritonéale diminuée</strong> et à des anomalies hormonales/inflammatoires locales favorisant l’implantation et la persistance des lésions.</p>\n\n      <h4>Caractéristique histologique principale</h4>\n\n      <ul>\n        <li>Composante de <span class=\"kw-clinique\">tissu endométrial</span> entouré d’un <strong><span class=\"kw-clinique\">stroma</span></strong></li>\n        <li>Comportement cyclique mimant celui de l’endomètre :\n          <ol>\n            <li>Croissance cyclique → desquamation → hémorragie pendant les règles</li>\n            <li>Sang et cellules desquamées <strong>non éliminés</strong> → <span class=\"kw-alerte\">réaction inflammatoire cyclique locale</span></li>\n          </ol>\n        </li>\n      </ul>\n\n      <h4>Provenance des lésions — arguments pour le reflux tubaire</h4>\n\n      <ul>\n        <li>FR de reflux tubaire ↗ le risque d’endométriose</li>\n        <li>Prédominance des lésions dans le <strong>compartiment postérieur du pelvis et à gauche</strong></li>\n        <li>Implants disséminés sur le trajet de circulation du liquide péritonéal (analogie avec les métastases du cancer de l’ovaire)</li>\n        <li><strong>Péritoine des femmes atteintes</strong> aurait une capacité diminuée d’élimination du sang et des cellules (le reflux tubaire survient chez la majorité des femmes, mais toutes ne développent pas une endométriose)</li>\n      </ul>\n\n      <h4>Mécanismes de croissance et de persistance</h4>\n\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Anomalies hormonales</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Surexpression du récepteur aux œstrogènes</span></strong><br>\n              <strong><span class=\"kw-def\">Résistance à la progestérone</span></strong><br>\n              <strong><span class=\"kw-def\">Surexpression de l’aromatase</span></strong><br>\n              → favorise croissance + persistance des lésions\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Réaction <span class=\"kw-etio\">inflammatoire</span></strong></td>\n            <td>\n              Production locale d’<span class=\"kw-clinique\">IL-6</span>, de <span class=\"kw-clinique\">TNF</span>, stress oxydatif<br>\n              → endométriose = <em>maladie <span class=\"kw-etio\">inflammatoire</span> locale</em> avec réponse immunitaire péritonéale\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Invasion / néoangiogenèse</strong></td>\n            <td>\n              Surexpression des <strong><span class=\"kw-clinique\">métalloprotéinases</span></strong><br>\n              Surexpression du <span class=\"kw-clinique\">VEGF</span><br>\n              → potentiel d’invasion et de néoangiogenèse marqué\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mécanismes des douleurs</h4>\n\n      <ul>\n        <li>Nociception · hyperalgie · <strong><span class=\"kw-def\">sensibilisation centrale</span></strong></li>\n        <li><strong>Corrélation</strong> entre <em>typologie</em> des douleurs et <em>localisation</em> des lésions</li>\n        <li><span class=\"kw-alerte\">Pas de lien</span> entre <em>intensité des symptômes</em> et <em>étendue/profondeur</em> de l’endométriose</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> Une endométriose <em>peu étendue</em> peut être <strong>très symptomatique</strong>, et inversement une atteinte profonde peut être <em>pauci-symptomatique</em>. Le bilan d’extension n’est <strong>jamais</strong> proportionné à la sévérité clinique.\n      </div>","frequence":0},{"id":"41-4","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir diagnostiquer une endométriose","contenu":"<p>Le <span class=\"kw-def\">diagnostic d’endométriose</span> est avant tout <strong>clinique</strong>. Les examens d’imagerie évaluent la <em>gravité et la cartographie</em> de la maladie ; leur normalité <strong>n’exclut pas</strong> le diagnostic (en particulier en cas d’endométriose superficielle).</p>\n\n      <h4>Circonstances diagnostiques</h4>\n\n      <ul>\n        <li>Diagnostic fortuit chez les femmes pauci/asymptomatiques (imagerie, <span class=\"kw-ttt\">chirurgie</span> incidente)</li>\n        <li>Symptômes plus marqués chez les femmes avec <strong>règles mensuelles + activité ovarienne non freinée</strong> par contraception hormonale :\n          <ul>\n            <li>Adolescentes</li>\n            <li>Femmes jeunes nullipares à l’arrêt de la contraception pour <span class=\"kw-ci\">grossesse</span></li>\n            <li>Femmes multipares avec contraception <strong>mécanique</strong> (DIU cuivre, stérilisation tubaire…)</li>\n          </ul>\n        </li>\n      </ul>\n\n      <h4>Triade symptomatique</h4>\n\n      <ul>\n        <li><strong>Symptômes douloureux de survenue cyclique</strong> rythmée par les règles ⭐</li>\n        <li><strong>Manifestations spécifiques d’organe</strong> (digestives, urinaires, scapulaires…)</li>\n        <li><span class=\"kw-alerte\">Infertilité</span></li>\n      </ul>\n\n      <h4>Symptômes douloureux gynécologiques</h4>\n\n      <table >\n        <thead>\n          <tr><th>Symptôme</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Dysménorrhée</strong><br><em>(1ᵉʳ symptôme dans la majorité des cas)</em></td>\n            <td>\n              <strong>Type</strong> : douleurs sourdes<br>\n              <strong>Topographie</strong> : abdomino-pelvienne (hypogastre, fosses iliaques, flancs, bas du dos)<br>\n              <strong>Délai</strong> : souvent dès les 1ʳᵉˢ règles<br>\n              <strong>Horaire</strong> : <span class=\"kw-clinique\">cyclique</span>, survenant juste avant les règles<br>\n              <strong>Durée</strong> : <span class=\"kw-chiffre\">1-2 jours</span>, parfois plus (crescendo)<br>\n              <strong>Associé</strong> : ménorragies souvent associées<br>\n              <strong>Calmants</strong> : <span class=\"kw-ttt\">AINS</span> ✅ ; pilule en mode cyclique ✅<br>\n              <em>Conséquence</em> : absentéisme scolaire ou professionnel\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Dyspareunie profonde</strong></td>\n            <td>\n              Déclenchée par les <strong>pénétrations profondes</strong>, généralement dans le cul-de-sac postérieur<br>\n              Causes possibles : adénomyose ; endométriose superficielle du cul-de-sac recto-utérin ; <strong>endométriose profonde</strong> (rétrocervicale, ligaments utéro-sacrés, culs-de-sac vaginaux) → <em>justifie une <span class=\"kw-imagerie\">IRM</span></em><br>\n              <em>Conséquence</em> : retentissement sexuel + diminue les chances de conception spontanée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Méno-/métrorragies douloureuses</strong></td>\n            <td>Évocateur d’<span class=\"kw-etio\">adénomyose</span> (toujours douloureuses dans ce contexte)</td>\n          </tr>\n          <tr>\n            <td><strong>Douleurs intermenstruelles</strong></td>\n            <td>\n              Pelviennes chroniques, entre les règles<br>\n              Causes : adhérences intra-abdominales des endométrioses évoluées ; mécanismes neuropathiques (obscurcissent le tableau clinique)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Dysménorrhées : primaire <span class=\"kw-bio\">vs</span> secondaire (à distinguer)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Primaire / essentielle</th><th>Secondaire / organique</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Survenue</strong></td>\n            <td><span class=\"kw-chiffre\">6-24 mois</span> après les 1ʳᵉˢ règles (cycles ovulatoires)</td>\n            <td>Tardive ; <em>pendant et en dehors des règles</em> ; <strong>s’aggrave</strong> au fil des cycles</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>Crampes pelviennes/lombaires isolées ± <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">diarrhée</span>, migraines, <span class=\"kw-clinique\">malaise</span> vagal</td>\n            <td>Accompagnée d’autres symptômes douloureux</td>\n          </tr>\n          <tr>\n            <td><strong>Intensité</strong></td>\n            <td>Modérée à sévère</td>\n            <td><span class=\"kw-alerte\">Sévère (EVA &gt; 7/10)</span></td>\n          </tr>\n          <tr>\n            <td><strong>Antalgie</strong></td>\n            <td>Répond aux <span class=\"kw-ttt\">antalgiques</span> usuels (antispasmodiques, <span class=\"kw-ttt\">paracétamol</span>, <span class=\"kw-ttt\">AINS</span>)</td>\n            <td>Résistante aux <span class=\"kw-ttt\">antalgiques</span> usuels</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Examen clinique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Éléments à rechercher</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>\n              Chronologie de la symptomatologie / survenue des règles<br>\n              Rechercher les <strong>dyspareunies profondes balistiques</strong><br>\n              Questionnaires de qualité de vie : <strong>EHP-30, EHP-5, SF-36</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen abdominal</strong></td>\n            <td>\n              Souvent pauvre : douleurs non spécifiques (palpation sensible sans défense)<br>\n              En crise douloureuse : peut mimer un abdomen chirurgical\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Spéculum</strong></td>\n            <td>\n              Réalisé avec délicatesse (cul-de-sac douloureux au contact)<br>\n              Souvent normal — peut mettre en évidence un <strong><span class=\"kw-clinique\">nodule</span> d’endométriose profonde</strong> infiltrant le vagin :<br>\n              → <span class=\"kw-clinique\">rétraction fibreuse</span>, <span class=\"kw-clinique\">lésion végétante</span>, <span class=\"kw-clinique\">microkystes noirs</span><br>\n              ± taches bleutées du vagin ou du col\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher vaginal (<span class=\"kw-alerte\">TV</span>)</strong></td>\n            <td>\n              <span class=\"kw-alerte\">À ne pas réaliser si patiente vierge</span><br>\n              <strong>Cul-de-sac postérieur souple mais sensible</strong> → endométriose superficielle du cul-de-sac recto-utérin<br>\n              <strong><span class=\"kw-clinique\">Nodule</span> fibreux / <span class=\"kw-clinique\">lésion</span> végétante palpable</strong> → endométriose profonde (cul-de-sac vaginal, ligaments utéro-sacrés, Douglas)<br>\n              <strong>Utérus augmenté + sensible</strong> (surtout en période menstruelle) → adénomyose<br>\n              <strong><span class=\"kw-clinique\">Masse</span> kystique ovarienne</strong> → endométriome<br>\n              Utérus rétroversé/peu mobile, ovaires peu mobiles → arguments en faveur\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Toucher rectal (TR)</strong></td>\n            <td>Utile surtout si suspicion de <strong><span class=\"kw-clinique\">nodule</span> d’endométriose profonde rétrocervicale</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le diagnostic d’endométriose est <em>clinique</em> : la <strong>coelioscopie diagnostique systématique</strong> et la preuve histologique <span class=\"kw-alerte\">ne sont pas nécessaires</span>. L’écho endovaginale + <span class=\"kw-imagerie\">IRM</span> pelvienne suffisent pour le bilan d’extension de 1ʳᵉ intention.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 35 — Anomalies cycle menstruel - métrorragie · 40 — Algies pelviennes</em></p>","frequence":1,"liens":[{"href":"https://radiopaedia.org/articles/endometriosis","label":"Radiopaedia : Endometriosis"}]},{"id":"41-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les conséquences de l’endométriose","contenu":"<p>Les <span class=\"kw-def\">conséquences</span> de l’endométriose se répartissent en <strong>3 axes</strong> : manifestations spécifiques d’organe (cataméniales), retentissement sur la fertilité, retentissement sur la qualité de vie. La <span class=\"kw-alerte\">non-corrélation</span> entre étendue lésionnelle et intensité des symptômes complique le <span class=\"kw-def\">pronostic</span> individuel.</p>\n\n      <h4>Manifestations spécifiques d’organe (cataméniales)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Atteinte</th><th>Symptômes</th><th>Causes possibles</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Digestive</strong></td>\n            <td>\n              <strong>Dyschésie</strong> (difficulté d’exonération) ± douleurs à la défécation<br>\n              Diarrhées cataméniales ; constipations sévères ; ballonnements\n            </td>\n            <td>\n              Localisations digestives — <strong>rectum / côlon sigmoïde</strong> (2/3 des atteintes digestives) → <em>justifie une <span class=\"kw-imagerie\">IRM</span></em><br>\n              Effet irritatif de lésions superficielles ou profondes sur le tube digestif / plexus hypogastriques inférieurs\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Urinaire</strong></td>\n            <td>\n              <strong>SFU cataméniaux</strong> : cystalgies cataméniales, <span class=\"kw-clinique\">pollakiurie</span> diurne et nocturne, urgenturie<br>\n              Impression d’IU avec <span class=\"kw-clinique\">ECBU stérile</span>\n            </td>\n            <td>\n              Endométriose profonde de la <strong>vessie</strong> → <em>justifie une <span class=\"kw-imagerie\">IRM</span></em><br>\n              Effet irritatif de lésions superficielles\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-alerte\">Rénale</span></strong></td>\n            <td>\n              <strong>Atrophie rénale à bas bruit</strong> (longtemps asymptomatique)<br>\n              Sténose urétérale → dilatation pyélocalicielle en amont (<span class=\"kw-chiffre\">5 %</span> des cas)\n            </td>\n            <td>Nodules profonds engainant / infiltrant les <strong>uretères</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Diaphragmatique / thoracique</strong></td>\n            <td>\n              <strong>Douleurs scapulaires ou basithoraciques droites</strong><br>\n              Épisodes de <span class=\"kw-alerte\">pneumothorax cataménial</span>\n            </td>\n            <td>Endométriose de l’<strong>hémicoupole diaphragmatique droite</strong>, pleurale, parenchyme pulmonaire</td>\n          </tr>\n          <tr>\n            <td><strong>Sciatique / sacrée</strong></td>\n            <td>Douleurs fessières, sciatalgies cataméniales</td>\n            <td>Compression des <strong>racines sacrées</strong> par endométriose profonde</td>\n          </tr>\n          <tr>\n            <td><strong>Mictionnelle (neurogène)</strong></td>\n            <td><strong>Dysuries cataméniales</strong></td>\n            <td>Endométriose profonde du vagin sur les <strong>nerfs splanchniques moteurs de la vessie</strong></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Infertilité — chiffres et mécanismes</h4>\n\n      <table >\n        <thead>\n          <tr><th>Fréquence</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>Endométriose chez les femmes infertiles</td>\n            <td><span class=\"kw-chiffre\">15-20 %</span></td>\n          </tr>\n          <tr>\n            <td>Infertilité chez les femmes endométriosiques</td>\n            <td><span class=\"kw-chiffre\">30-50 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <table >\n        <thead>\n          <tr><th>Mécanisme</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sexuel</strong></td>\n            <td>Dyspareunie + <span class=\"kw-clinique\">asthénie</span> secondaire aux douleurs chroniques → <span class=\"kw-ttt\">réduction</span> du nombre de rapports</td>\n          </tr>\n          <tr>\n            <td><strong>Pelvien</strong></td>\n            <td>\n              <strong>Obstruction</strong> intratubaire ou tubo-ovarienne (empêche la rencontre des gamètes)<br>\n              Inflammation intrapéritonéale / intratubaire (effet néfaste sur l’interaction ovule-spermatozoïde)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Utérin</strong></td>\n            <td><span class=\"kw-etio\">Adénomyose</span> : défaut d’implantation embryonnaire</td>\n          </tr>\n          <tr>\n            <td><strong>Ovarien</strong></td>\n            <td>Destruction du parenchyme ovarien par <strong>endométriome</strong> → altération de la <span class=\"kw-alerte\">réserve ovarienne</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-clinique\">Évolution</span> des lésions</h4>\n\n      <ul>\n        <li>Adhérences intrapelviennes et intra-abdominales</li>\n        <li>Modifications de l’<strong>architecture du pelvis</strong> et des organes</li>\n        <li>Conséquences potentielles : <span class=\"kw-alerte\">phénomènes douloureux</span> et/ou <span class=\"kw-alerte\">infertilité</span></li>\n        <li><span class=\"kw-clinique\">Évolution</span> <span class=\"kw-chiffre\">imprévisible</span> et variable d’une patiente à l’autre</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong><span class=\"kw-alerte\">Drapeaux rouges</span> à connaître.</strong> Toute <em>sciatalgie cataméniale</em>, <em><span class=\"kw-etio\">pneumothorax</span> cataménial</em> ou <em>douleur scapulaire cyclique</em> chez une femme jeune doit faire évoquer une <span class=\"kw-alerte\">endométriose extra-pelvienne</span>. Une <strong>atrophie rénale</strong> de découverte fortuite chez une femme symptomatique (dyspareunie, dysménorrhée) impose la recherche d’une endométriose urétérale.\n      </div>","frequence":1},{"id":"41-6","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications et l’objectif de l’imagerie d’une endométriose","contenu":"<p>L’<span class=\"kw-def\">imagerie</span> n’est <strong>pas indispensable au diagnostic</strong> (avant tout clinique). Son objectif est l’<em>évaluation de la gravité</em> et la <em>cartographie</em> des lésions. Examens réalisés préférentiellement par des <strong>échographistes/radiologues référents en endométriose</strong>.</p>\n\n      <h4>Bilan de 1ʳᵉ intention</h4>\n\n      <ul>\n        <li><strong><span class=\"kw-imagerie\">Échographie</span> pelvienne par voie endovaginale</strong></li>\n        <li><strong><span class=\"kw-imagerie\">IRM</span> pelvienne</strong></li>\n        <li>Imagerie réalisée si possible <em>après lavement rectal</em></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Un <em>bilan d’imagerie négatif n’élimine pas formellement une endométriose</em> — les implants péritonéaux d’endométriose superficielle ne sont pas toujours visibles. Le diagnostic reste clinique.\n      </div>\n\n      <h4>Performances comparées des examens (à distinguer)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Indications · cibles</th><th>Sémiologie</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Échographie</span> pelvienne endovaginale</strong></td>\n            <td>\n              1ʳᵉ intention systématique<br>\n              Plus sensible que l’<span class=\"kw-imagerie\">IRM</span> pour le <strong>recto-sigmoïde antérieur</strong>\n            </td>\n            <td>\n              <span class=\"kw-etio\">Endométriome ovarien</span> : kyste à contenu finement granité, <strong>persistant sur plusieurs cycles</strong> (≠ kyste <span class=\"kw-etio\">hémorragique</span>)<br>\n              <span class=\"kw-etio\">Adénomyose</span> : gros utérus globuleux/asymétrique, épaississement du mur postérieur, échostructure irrégulière, images kystiques intra-myométriales, <span class=\"kw-radio\">effacement de la ligne de jonction</span><br>\n              <span class=\"kw-etio\">Nodules profonds rétractiles</span> : ligaments utéro-sacrés, vessie, recto-sigmoïde<br>\n              <span class=\"kw-radio\">Épaississement</span> des ligaments utéro-sacrés<br>\n              <span class=\"kw-alerte\">Complications</span> : hématosalpinx, sténoses urétérales avec dilatation en amont\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">IRM</span> abdomino-pelvienne</strong></td>\n            <td>\n              Cartographie précise des lésions intra-pelviennes et abdominales<br>\n              Plus sensible (moins spécifique) que l’écho pour : <strong>ligaments utéro-sacrés, vagin, cloison recto-vaginale</strong><br>\n              Indications spécifiques : signes d’endométriose profonde, infertilité, endométriome, résistance au traitement, <span class=\"kw-clinique\">masse</span> ovarienne indéterminée\n            </td>\n            <td>\n              <span class=\"kw-etio\">Kystes endométriosiques</span> : <strong><span class=\"kw-radio\">HyperT1-SAT</span></strong> (saturation graisse) + <strong><span class=\"kw-radio\">HypoT2</span></strong> (sang)<br>\n              <span class=\"kw-etio\">Nodules profonds</span> : formations <strong>en étoile</strong>, HypoT1 + HypoT2, rétractiles, infiltrantes (rectum, sigmoïde, vagin, vessie), pouvant contenir des microkystes<br>\n              <span class=\"kw-etio\">Adénomyose</span> : élargissement de la <strong><span class=\"kw-radio\">zone jonctionnelle</span></strong> + microspots en hypersignal dans le myomètre<br>\n              <span class=\"kw-alerte\">Complications</span> : hématosalpinx, sténose urétérale avec hydronéphrose, infiltrations\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examens orientés (cas sévères)</strong></td>\n            <td>Selon localisation visualisée sur écho/<span class=\"kw-imagerie\">IRM</span></td>\n            <td>\n              <strong><span class=\"kw-imagerie\">Échographie</span> endorectale + coloscanner</strong> : endométriose colorectale<br>\n              <strong>Cystoscopie, uroscanner, uro-<span class=\"kw-imagerie\">IRM</span></strong> : endométriose de l’appareil urinaire<br>\n              <strong><span class=\"kw-imagerie\">IRM</span> et <span class=\"kw-imagerie\">TDM</span> du diaphragme</strong> : endométriose diaphragmatique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td><span class=\"kw-alerte\">Non spécifique</span></td>\n            <td>\n              <strong><span class=\"kw-bio\">CA-125</span></strong> : augmentation possible (endométriose ovarienne/péritonéale diffuse) — <em>ancien référentiel</em>, ne fait <strong>pas partie</strong> du bilan actuel\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Coelioscopie</span></strong></td>\n            <td>\n              Diagnostic de certitude <strong>mais non indispensable</strong><br>\n              Permet le traitement des lésions<br>\n              En cas d’infertilité : <span class=\"kw-def\">classification</span> pronostique <em>AFSr</em> (American Fertility Society revised)\n            </td>\n            <td>Exploration directe + <span class=\"kw-bio\">biopsie</span> ciblée + analyse anatomopathologique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Piège classique.</strong> En cas d’<em>endométriome ovarien diagnostiqué</em>, il faut <strong>rechercher systématiquement une endométriose profonde associée</strong> (souvent sous-estimée si on s’arrête à l’endométriome). C’est l’indication classique du couple écho + <span class=\"kw-imagerie\">IRM</span>.\n      </div>","frequence":0},{"id":"41-7","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la stratégie de prise en charge d’une endométriose","contenu":"<p>La <span class=\"kw-def\">prise en charge</span> est <strong>symptomatique</strong> : on traite les <em>conséquences</em> (douleur, infertilité) plutôt que la maladie elle-même. Le traitement médical hormonal est <strong>suspensif</strong>, sans effet curatif. Le traitement chirurgical est réservé aux échecs/intolérances et doit privilégier <em>une seule intervention bien menée</em>.</p>\n\n      <h4>Traitement médical — 1ʳᵉ intention systématique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td>1ʳᵉ intention <strong>empirique</strong> devant toute suspicion d’endométriose — <span class=\"kw-alerte\">sans nécessité de preuve histologique préalable</span></td>\n          </tr>\n          <tr>\n            <td><strong>Objectif</strong></td>\n            <td>Améliorer les <strong>symptômes douloureux</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Traitements non hormonaux</strong></td>\n            <td>\n              <strong><span class=\"kw-ttt\">Paracétamol</span></strong><br>\n              <strong><span class=\"kw-ttt\">Antispasmodiques</span></strong><br>\n              <strong><span class=\"kw-ttt\">AINS</span></strong> (<span class=\"kw-ci\">à éviter</span> au long cours)<br>\n              Compléments : acupuncture, ostéopathie, yoga<br>\n              Recours au <strong>centre anti-douleur</strong> si chronicité + résistance\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Thérapies hormonales</strong></td>\n            <td>\n              <strong>Mécanisme</strong> : blocage de l’activité ovarienne en continu → <span class=\"kw-ttt\">réduction</span>/suppression du flux menstruel, restauration de la sensibilité à la progestérone, action atrophique sur le tissu endométrial, diminution de la prolifération + néo-angiogenèse + stress oxydant<br>\n              <strong>1ʳᵉ intention</strong> : <span class=\"kw-ttt\">DIU au lévonorgestrel</span><br>\n              <strong>2ᵉ intention</strong> : contraceptions <span class=\"kw-ttt\">microprogestatives</span> ; <span class=\"kw-ttt\">COP en continu</span> (éviter les hémorragies de privation)<br>\n              <strong>Effets</strong> : antalgie + arrêt de croissance des lésions + réduction du risque de récidive chez les opérées<br>\n              <strong>Durée</strong> : long, poursuivi <em>jusqu’au désir de <span class=\"kw-ci\">grossesse</span></em> ou <em>jusqu’à la ménopause</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>À retenir.</strong> Les thérapies hormonales ont un effet <em>suspensif</em>, <span class=\"kw-alerte\">sans effet curatif</span> sur la maladie. L’arrêt avant la ménopause expose à une <strong>reprise évolutive</strong> et à la perte de l’effet <span class=\"kw-ttt\">antalgique</span> en quelques mois.\n      </div>\n\n      <h4>Traitement chirurgical — 2ᵈ intention</h4>\n\n      <table >\n        <thead>\n          <tr><th>Axe</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td>\n              Attentes de la patiente<br>\n              <strong>Absence d’efficacité</strong> des traitements médicaux<br>\n              <strong><span class=\"kw-ci\">Intolérance</span></strong> aux traitements médicaux bien conduits\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Objectifs</strong></td>\n            <td>\n              Résection / destruction des lésions ; réparation des organes atteints<br>\n              Traiter douleur + infertilité<br>\n              Évaluation diagnostique, pronostique et thérapeutique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Voie</strong></td>\n            <td><strong>Coelioscopique</strong> (préférée à la laparotomie)</td>\n          </tr>\n          <tr>\n            <td><strong>Modalités</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Une seule intervention bien menée</span> ✅<br>\n              <strong>Éviter les chirurgies itératives incomplètes</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Récidive après <span class=\"kw-ttt\">chirurgie</span></strong></td>\n            <td>\n              Aménorrhée hormonale post-<span class=\"kw-ttt\">chirurgie</span> → ↘ risque de récidive<br>\n              Récidive des douleurs ≠ récidive lésionnelle (peut être traitée médicalement)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Modalités chirurgicales selon le type de <span class=\"kw-clinique\">lésion</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Lésion</th><th>Geste</th><th>Spécificités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Endométriose superficielle</strong></td>\n            <td><span class=\"kw-ttt\">Exérèse</span> (résection) ou ablation (destruction)</td>\n            <td>Accessible à la majorité des chirurgiens</td>\n          </tr>\n          <tr>\n            <td><strong>Endométriome ovarien</strong></td>\n            <td><span class=\"kw-ttt\">Exérèse</span> (kystectomie) ou ablation</td>\n            <td>\n              Indication <span class=\"kw-alerte\">non systématique</span> (réponse possible au traitement médical)<br>\n              Risques : <strong>↘ réserve ovarienne</strong> (absence de plan de clivage), insuffisance ovarienne définitive en cas de <span class=\"kw-ttt\">chirurgie</span> itérative ⚠️\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Endométriose profonde</strong></td>\n            <td>Résection nodulaire</td>\n            <td>Nécessite une <strong>réelle expertise</strong> → équipe chirurgicale multidisciplinaire spécialisée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Adénomyose — particularités thérapeutiques</h4>\n\n      <ol>\n        <li><strong>1ʳᵉ intention</strong> : <span class=\"kw-ttt\">DIU au lévonorgestrel</span> (action atrophiante)</li>\n        <li><strong>2ᵈ intention</strong> (échec) :\n          <ul>\n            <li><strong><span class=\"kw-ttt\">Endométrectomie</span></strong> (conservateur, <span class=\"kw-ttt\">réduction</span> endométriale)</li>\n            <li><strong><span class=\"kw-ttt\">Hystérectomie</span></strong> si échec ou refus du conservateur, en l’absence de désir de <span class=\"kw-ci\">grossesse</span></li>\n          </ul>\n        </li>\n      </ol>\n\n      <h4>Prise en charge de l’infertilité (AMP)</h4>\n\n      <ul>\n        <li><strong>1ᵉʳ temps</strong> : interruption du traitement hormonal (contraceptif) ; <strong>bilan complet</strong> à la recherche d’autres causes (dysovulation, altérations spermatiques…)</li>\n        <li><strong>2ᵈ temps</strong> : <span class=\"kw-ttt\">AMP</span> guidée au cas par cas (<span class=\"kw-def\">stade</span>, âge, délai d’infertilité, examens) ; préservation de la fertilité envisagée si endométriome ovarien / réserve ovarienne altérée</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> En cas d’infertilité avec endométriome, une discussion s’engage entre <strong>FIV (possible même en cas d’endométriome)</strong> et <strong><span class=\"kw-ttt\">chirurgie</span></strong> — la chirurgie n’est <span class=\"kw-alerte\">pas</span> systématique car elle expose à une chute de la réserve ovarienne.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 36 — Contraception · 39 — Assistance médicale à la procréation · 40 — Algies pelviennes</em></p>","frequence":1}],"astuces":[],"strategie":{"hospit":"<p><strong>Endométriose profonde <span class=\"q\">— recours aux équipes expertes</span></strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> de l'<span class=\"kw-etio\">endométriose profonde</span> nécessite une <strong>réelle expertise</strong> → référer aux <span class=\"kw-def\">équipes chirurgicales multidisciplinaires spécialisées</span></li><li><span class=\"kw-imagerie\">Échographie pelvienne</span> et <span class=\"kw-imagerie\">IRM</span> réalisées préférentiellement par des <strong>radiologues référents</strong> en endométriose</li></ul><p><strong>Infertilité <span class=\"q\">— orientation vers l'AMP</span></strong></p><ul><li>Discussion au cas par cas entre <span class=\"kw-ttt\">FIV</span> (possible même en présence d'<span class=\"kw-etio\">endométriomes</span>) et <strong><span class=\"kw-ttt\">chirurgie</span></strong></li><li>En cas d'<span class=\"kw-etio\">endométriome ovarien</span> ou d'altération de la <span class=\"kw-alerte\">réserve ovarienne</span> → envisager une <span class=\"kw-ttt\">préservation de la fertilité</span></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Sténose urétérale</span> avec <span class=\"kw-alerte\">hydronéphrose</span> ou <span class=\"kw-alerte\">atrophie rénale silencieuse</span> — longtemps asymptomatique (<span class=\"kw-chiffre\">5 %</span> des endométrioses profondes)</li><li><span class=\"kw-alerte\">Pneumothorax cataménial</span> récidivant — évoquer une <span class=\"kw-etio\">endométriose diaphragmatique</span>, <span class=\"kw-etio\">pleurale</span> ou <span class=\"kw-etio\">pulmonaire</span></li><li><span class=\"kw-alerte\">Insuffisance ovarienne prématurée</span> après chirurgies itératives des <span class=\"kw-etio\">endométriomes</span> récidivés — conséquence de la destruction du parenchyme ovarien sans plan de clivage</li><li><span class=\"kw-alerte\">Sciatalgies cataméniales</span> ou douleurs fessières cycliques — compression des <span class=\"kw-etio\">racines sacrées</span> par endométriose profonde</li><li>Toute <span class=\"kw-alerte\">douleur cyclique extra-pelvienne</span> (scapulaire droite, basithoracique) chez la femme jeune — évoquer une <span class=\"kw-etio\">endométriose extra-pelvienne</span></li></ul>","principes":"<p>PEC <strong>symptomatique</strong> : on traite les <em>conséquences</em> (douleur, infertilité), pas la maladie elle-même. <span class=\"kw-ttt\">Traitement médical hormonal</span> = <strong>1ʳᵉ intention</strong> empirique, <strong>suspensif</strong> (sans effet curatif). <span class=\"kw-ttt\">Chirurgie</span> = <strong>2ᵉ intention</strong>, réservée aux échecs/intolérances.</p><p><strong>Traitement non hormonal</strong></p><ul><li><span class=\"kw-ttt\">Paracétamol</span> · <span class=\"kw-ttt\">antispasmodiques</span> · <span class=\"kw-ttt\">AINS</span> (<span class=\"kw-ci\">AINS à éviter au long cours</span>)</li><li>Recours au <strong>centre anti-douleur</strong> si <span class=\"kw-clinique\">douleur chronique</span> résistante aux <span class=\"kw-ttt\">antalgiques</span> usuels</li></ul><p><strong>Thérapies hormonales <span class=\"q\">— traitement suspensif en continu</span></strong></p><p>Arrêt avant ménopause → risque de <span class=\"kw-alerte\">reprise évolutive</span> et de perte de l'effet <span class=\"kw-ttt\">antalgique</span></p><ul><li><strong>1ʳᵉ intention</strong> : <span class=\"kw-ttt\">DIU au lévonorgestrel</span></li><li><strong>2ᵉ intention</strong> : <span class=\"kw-ttt\">contraceptions microprogestatives</span> ; <span class=\"kw-ttt\">COP en continu</span> (pour éviter les hémorragies de privation)</li><li>Durée : long, poursuivi jusqu'au <strong>désir de <span class=\"kw-ci\">grossesse</span></strong> ou jusqu'à la <span class=\"kw-clinique\">ménopause</span></li></ul><p><strong><span class=\"kw-ttt\">Chirurgie</span> cœlioscopique <span class=\"q\">— 2ᵉ intention</span></strong></p><p>Post-<span class=\"kw-ttt\">chirurgie</span> : <span class=\"kw-ttt\">aménorrhée hormonale</span> pour réduire le risque de <span class=\"kw-alerte\">récidive lésionnelle</span></p><ul><li><strong>Indications</strong> : absence d'efficacité ou <span class=\"kw-ci\">intolérance aux traitements médicaux</span> bien conduits</li><li><strong>Voie</strong> : <span class=\"kw-ttt\">cœlioscopique</span> (préférée à la laparotomie)</li><li><span class=\"kw-alerte\">Une seule intervention bien menée</span> — éviter les chirurgies itératives incomplètes</li><li>Endométriose profonde : <span class=\"kw-ttt\">résection nodulaire</span> par équipe multidisciplinaire experte</li></ul><p><strong>Infertilité — AMP</strong></p><ul><li><strong>1ᵉʳ temps</strong> : interruption du traitement hormonal + <strong>bilan complet</strong> (<span class=\"kw-bio\">dysovulation</span>, <span class=\"kw-bio\">altérations spermatiques</span>…)</li><li><strong>2ᵈ temps</strong> : <span class=\"kw-ttt\">AMP</span> guidée au cas par cas (<span class=\"kw-def\">stade</span>, âge, délai d'infertilité, examens)</li><li><span class=\"kw-ttt\">FIV</span> possible même en présence d'<span class=\"kw-etio\">endométriomes</span> — la <span class=\"kw-ttt\">chirurgie</span> n'est <span class=\"kw-ci\">pas systématique</span> (risque de <span class=\"kw-alerte\">chute de la réserve ovarienne</span>)</li></ul>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/endometriosis","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/adenomyosis","label":"radiopaedia.org"}],"cards":[{"i":"1b6c59f861db","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Quelles sont les différentes catégories anatomiques des lésions d'endométriose ?","a":"<ul><li>L'<strong>endométriose péritonéale superficielle</strong> : lésions de petite taille limitées au péritoine.</li><li>L'<strong>endométriome</strong> : lésion kystique ovarienne (kyste endométriosique).</li><li>L'<strong>endométriose pelvienne profonde</strong> : nodules infiltrant à &gt; <strong>5 mm</strong> sous le péritoine.</li><li>Les localisations à <strong>distance</strong> : rares mais possibles (ex: pulmonaire, cérébrale).</li></ul>"},{"i":"4948cd5bd45b","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Comment distingue-t-on une dysménorrhée primaire d'une dysménorrhée secondaire ?","a":"<ul><li>La <strong>dysménorrhée primaire</strong> (ou essentielle) apparaît <strong>6 à 24 mois après les premières règles</strong>, est idiopathique et sensible aux antalgiques usuels.</li><li>La <strong>dysménorrhée secondaire</strong> apparaît plus tardivement, s'aggrave au fil des cycles, est souvent estimée à un score EVA &gt; 7/10 et est résistante aux antalgiques.</li></ul>"},{"i":"86f0f83b32ec","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Dans quel contexte l'endométriose devient-elle une maladie ?","a":"<p>L'endométriose devient une maladie lorsqu'elle se traduit par des symptômes tels que des <strong>douleurs</strong> et/ou une <strong>infertilité</strong>.</p>"},{"i":"9c65f2603798","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Quelle est la définition de l'adénomyose ?","a":"<p>L'adénomyose est caractérisée par une <strong>infiltration diffuse ou focale du myomètre</strong> par des cellules endométriales, conduisant à la formation de <strong>microkystes endométriaux intra-myométriaux</strong>.</p>"},{"i":"a4ba79a2ef61","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Quelle est la définition histologique de l'endométriose ?","a":"<p>L'endométriose est définie histologiquement par la présence de <strong>tissu de type endométrial en dehors de la cavité utérine</strong>.</p>"},{"i":"d06e2d46f409","n":41,"o":"41-1","u":"Définition","t":"Connaître la définition des dysménorrhées, de l’endométriose, de l’adénomyose","q":"Quelle est la définition d'une dysménorrhée ?","a":"<p>Une dysménorrhée correspond à des <strong>règles douloureuses</strong>, c'est-à-dire des douleurs pelviennes contemporaines des menstruations.</p>"},{"i":"2ea418a38365","n":41,"o":"41-2","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","q":"Quelle est la prévalence globale de l'endométriose chez les femmes en âge de procréer ?","a":"<p>La prévalence globale de l'endométriose est estimée entre <strong>6 et 15 %</strong> des femmes en âge de procréer, toutes formes confondues.</p>"},{"i":"504bd05970fe","n":41,"o":"41-2","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","q":"Quel est le délai moyen avant le diagnostic d'endométriose ?","a":"<p>Le délai diagnostique de l'endométriose est de <strong>7 à 10 ans</strong> selon les études.</p>"},{"i":"903b76b975eb","n":41,"o":"41-2","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","q":"Quels sont les principaux facteurs de risque de l'endométriose liés au reflux tubaire menstruel ?","a":"<ul><li><strong>Ménarche précoce</strong></li><li><strong>Nulliparité</strong></li><li><strong>Cycles courts</strong>, <strong>hyperménorrhée</strong>, <strong>ménorragie</strong></li><li><strong>Anomalie müllérienne</strong> (malformation utérine)</li><li><strong>Geste endo-utérin</strong></li></ul>"},{"i":"cf4aebdc3124","n":41,"o":"41-2","u":"Epidémiologie","t":"Connaître l’épidémiologie de l’endométriose, de l’adénomyose","q":"Quelle est la prévalence de l'adénomyose et son association avec l'endométriose ?","a":"<p>L'adénomyose pourrait concerner près de <strong>50 %</strong> des femmes, avec une incidence augmentant après <strong>35 ans</strong>. Elle est souvent <strong>associée</strong> à l'endométriose.</p>"},{"i":"242be3302c54","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Quelle est la triade symptomatique classique de l'endométriose chez une femme avec règles mensuelles et activité ovarienne non freinée ?","a":"<p>La triade symptomatique typique de l'endométriose comprend :</p><ul><li>Des <strong>symptômes douloureux de survenue cyclique</strong> rythmée par les règles.</li><li>Des <strong>manifestations spécifiques d'organe</strong> (digestives, urinaires, scapulaires, etc.).</li><li>L'<strong>infertilité</strong>.</li></ul>"},{"i":"5e4432e86b1a","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Quels sont les signes à rechercher lors de l'examen clinique (spéculum, toucher vaginal, toucher rectal) suggérant une endométriose ?","a":"<p>Les signes cliniques orientant vers une endométriose sont :</p><ul><li><strong>Au spéculum</strong> : souvent normal, mais peut révéler un <strong>nodule d'endométriose profonde infiltrant le vagin</strong> (rétraction fibreuse, lésion végétante, microkystes noirs ± taches bleutées du vagin ou du col).</li><li><strong>Au toucher vaginal</strong> :</li><ul><li><strong>Cul-de-sac postérieur souple mais sensible</strong> : suggère une endométriose superficielle du cul-de-sac recto-utérin.</li><li><strong>Nodule fibreux / lésion végétante palpable</strong> : évoque une endométriose profonde (cul-de-sac vaginal, ligaments utéro-sacrés, Douglas).</li><li><strong>Utérus augmenté de taille + sensible</strong> (surtout en période menstruelle) : oriente vers une <strong>adénomyose</strong>.</li><li><strong>Masse kystique ovarienne</strong> : signe un <strong>endométriome</strong>.</li><li>Utérus rétroversé/peu mobile, ovaires peu mobiles sont des arguments en faveur.</li></ul><li><strong>Au toucher rectal</strong> : utile si suspicion de <strong>nodule d'endométriose profonde rétrocervicale</strong>.</li></ul>"},{"i":"8fb5670d5136","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Quelles sont les caractéristiques cliniques de la dysménorrhée d'origine endométriosique ?","a":"<p>La dysménorrhée endométriosique présente les caractéristiques suivantes :</p><ul><li>C'est le <strong>premier symptôme dans la majorité des cas</strong>.</li><li>Type de douleur : <strong>sourde</strong>.</li><li>Topographie : <strong>abdomino-pelvienne</strong> (hypogastre, fosses iliaques, flancs, bas du dos).</li><li>Délai : souvent dès les <strong>premières règles</strong>.</li><li>Horaire : <strong>cyclique</strong>, survenant juste <strong>avant les règles</strong>.</li><li>Durée : généralement <strong>1-2 jours</strong>, parfois plus (souvent en crescendo).</li><li>Souvent associée à des <strong>ménorragies</strong>.</li><li>Calmants : <strong>AINS</strong> et pilule en mode cyclique sont souvent efficaces initialement.</li><li>Conséquence : <strong>absentéisme scolaire ou professionnel</strong> fréquent.</li></ul>"},{"i":"d443dcf6ddd0","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Comment distinguer une dysménorrhée primaire d'une dysménorrhée secondaire, évocatrice d'endométriose ?","a":"<p>Les éléments clés pour distinguer une dysménorrhée primaire d'une dysménorrhée secondaire, potentiellement liée à l'endométriose, sont :</p><ul><li><strong>Survenue</strong> : la primaire apparaît 6-24 mois après les 1ères règles (cycles ovulatoires) ; la secondaire est <strong>tardive</strong>, survient pendant et en dehors des règles, et <strong>s'aggrave au fil des cycles</strong>.</li><li><strong>Clinique</strong> : la primaire se manifeste par des crampes pelviennes/lombaires isolées ; la secondaire est <strong>accompagnée d'autres symptômes douloureux</strong>.</li><li><strong>Intensité</strong> : la primaire est modérée à sévère ; la secondaire est <strong>sévère (EVA > 7/10)</strong>.</li><li><strong>Antalgie</strong> : la primaire répond aux antalgiques usuels (antispasmodiques, paracétamol, AINS) ; la secondaire est <strong>résistante aux antalgiques usuels</strong>.</li></ul>"},{"i":"db0ad86aad26","n":41,"o":"41-4","u":"Diagnostic positif","t":"Savoir diagnostiquer une endométriose","q":"Quelle est l'importance du diagnostic clinique dans l'endométriose et quelle est la place de la cœlioscopie et de l'histologie ?","a":"<p>Le diagnostic d'endométriose est <strong>avant tout clinique</strong>. La cœlioscopie diagnostique systématique et la preuve histologique <strong>ne sont pas nécessaires pour le diagnostic positif</strong>. L'échographie endovaginale et l'IRM pelvienne sont suffisantes pour le bilan d'extension de première intention.</p>"},{"i":"288978c4d3f3","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Quelles sont les manifestations urinaires de l'endométriose et quel est le risque rénal associé ?","a":"<p>Les manifestations urinaires comprennent des <strong>syndromes fonctionnels urinaires (SFU) cataméniaux</strong> tels que :</p><ul><li><strong>Cystalgies cataméniales</strong>.</li><li>Pollakiurie diurne et nocturne.</li><li>Urgenturie.</li><li>Une impression d'infection urinaire avec <strong>ECBU stérile</strong>.</li></ul><p>Le risque rénal majeur est l'<strong>atrophie rénale à bas bruit</strong> due à une <strong>sténose urétérale</strong>, pouvant entraîner une <strong>dilatation pyélocalicielle en amont</strong> dans environ <strong>5 %</strong> des cas.</p>"},{"i":"289ab9af0398","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Comment l'endométriose affecte-t-elle la fertilité ?","a":"<p>L'endométriose affecte la fertilité par plusieurs mécanismes :</p><ul><li>L'<strong>obstruction intratubaire</strong> ou tubo-ovarienne qui empêche la rencontre des gamètes.</li><li>L'<strong>inflammation intrapéritonéale</strong> ou intratubaire ayant un effet néfaste sur l'interaction ovule-spermatozoïde.</li><li>L'<strong>adénomyose</strong> (endométriose utérine) peut causer un défaut d'implantation embryonnaire.</li><li>Les <strong>endométriomes ovariens</strong> peuvent détruire le parenchyme ovarien et altérer la réserve ovarienne.</li><li>Les <strong>adhérences intrapelviennes</strong> et intra-abdominales modifient l'architecture du pelvis.</p>"},{"i":"565b6225f5f2","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Quels sont les trois axes principaux des conséquences de l'endométriose ?","a":"<p>Les trois axes principaux des conséquences de l'endométriose sont :</p><ul><li>Les <strong>manifestations spécifiques d'organe</strong> (cataméniales).</li><li>Le <strong>retentissement sur la fertilité</strong>.</li><li>Le <strong>retentissement sur la qualité de vie</strong>.</li></ul>"},{"i":"99b56947bac0","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Quelles sont les principales manifestations digestives de l'endométriose ?","a":"<p>Les principales manifestations digestives de l'endométriose comprennent :</p><ul><li>La <strong>dyschésie</strong> (difficulté d'exonération) ± douleurs à la défécation.</li><li>Les <strong>diarrhées cataméniales</strong>.</li><li>Les constipations sévères.</li><li>Les ballonnements.Ces symptômes sont souvent observés en cas d'atteinte du <strong>rectum</strong> ou du <strong>côlon sigmoïde</strong>.</p>"},{"i":"c9fe28105841","n":41,"o":"41-5","u":"Diagnostic positif","t":"Connaître les conséquences de l’endométriose","q":"Quels sont les signes d'alerte (drapeaux rouges) qui doivent faire évoquer une endométriose extra-pelvienne ?","a":"<p>Les signes d'alerte pour une endométriose extra-pelvienne sont :</p><ul><li>Toute <strong>sciatalgie cataméniale</strong>.</li><li>Un <strong>pneumothorax cataménial</strong>.</li><li>Une <strong>douleur scapulaire cyclique</strong> chez une femme jeune.</li><li>Une <strong>atrophie rénale</strong> de découverte fortuite chez une femme présentant des symptômes comme une dyspareunie ou une dysménorrhée peut également orienter vers une endométriose urétérale.</p>"}]};